\section{练习}

\begin{exercise}[$\star$]\label{exo:b3:quantum-angular-momentum:1}
(a) 由正则对易子推出 $[\hat L_x, \hat L_y] = \iu\hbar\hat L_z$。(b) 证明 $[\hat L^2, \hat L_z] = 0$。(c) 证明 $[\hat L_z, \hat x] = \iu\hbar\hat y$：$\hat L_z$ 产生什么变换？(d) 三个分量为何没有共同的本征基？其中是否存在一个特殊态（指出是哪一个）？
\end{exercise}

\begin{exercise}[$\star$]\label{exo:b3:quantum-angular-momentum:2}
对 $l = 1$，在基 $\{\ket{1,1}, \ket{1,0}, \ket{1,-1}\}$ 中：
(a) 写出 $\hat L_z$ 的矩阵；(b) 用升降公式写出 $\hat L_+$ 和 $\hat L_-$；(c) 组装 $\hat L_x$，并检验其本征值为 $\hbar, 0, -\hbar$；(d) 对 $L_x =
+\hbar$ 的态沿 $z$ 方向测量，求三种结果的概率。
\end{exercise}

\begin{exercise}[$\star$]\label{exo:b3:quantum-angular-momentum:3}
一氧化碳：键长 \qty{0.113}{nm}，约化质量 $\qty{1.14e-26}{kg}$。(a) 计算 $I$ 及 $B = \hbar^2/2I$（以 meV 为单位）。(b) 求 $J = 1 \leftarrow 0$ 谱线的频率和波长。(c) 求接下来两条谱线。(d) 天文学家将梳状谱线间距测量到五位有效数字：她得到的是何种分子量？精度如何？
\end{exercise}

\begin{exercise}[$\star$]\label{exo:b3:quantum-angular-momentum:4}
粒子处于 $l = 2$ 的态。(a) 列出测量 $L_z$ 的所有可能结果。(b) 用 $\cos\theta = m/\sqrt{l(l+1)}$ 计算 $\vect L$ 与 $z$ 轴之间的最小夹角。(c) 为什么该夹角永远不能为零？(d) 证明当 $l \to \infty$ 时最小夹角趋于零：经典矢量得以恢复。
\end{exercise}

\begin{exercise}[$\star\star$]\label{exo:b3:quantum-angular-momentum:5}
$-\hbar^2\Delta$ 的角向部分为 $\hat L^2$，且
\[
\hat L^2 = -\hbar^2\Big[\frac{1}{\sin\theta}\,\partial_\theta
(\sin\theta\,\partial_\theta) +
\frac{1}{\sin^2\theta}\,\partial_\varphi^2\Big] .
\]
(a) 验证 $Y_1^0 \propto \cos\theta$ 的 $\hat L^2$ 本征值为 $2\hbar^2$。(b) 同样验证 $Y_1^{\pm1} \propto \sin\theta\,
\eu^{\pm\iu\varphi}$，并给出其 $\hat L_z$ 本征值。(c) 检验其宇称。(d) 不计算任何积分，为何必有 $\braket{Y_1^0}{Y_1^1} = 0$？
\end{exercise}

\begin{exercise}[$\star\star$]\label{exo:b3:quantum-angular-momentum:6}
哪条转动谱线最亮？能级 $J$ 的布居数 $\propto (2J+1)\,\eu^{-BJ(J+1)/k_{\text{B}}T}$。(a) 解释这两个因子。(b) 证明极大值位于 $J_{\max} \approx
\sqrt{k_{\text{B}}T/2B} - \tfrac12$ 附近。(c) 对温度为 \qty{10}{K}（暗云）和 \qty{300}{K} 的 CO，哪些谱线占主导？(d) 反推：观测到的 CO 谱阶在 $J = 7$ 处达到峰值，说明温度为多少？
\end{exercise}

\begin{exercise}[$\star\star$]\label{exo:b3:quantum-angular-momentum:7}
正常塞曼效应。一条波长为 \qty{500}{nm} 的谱线来自 $l = 2 \to l = 1$ 的跃迁，置于磁场 $B = \qty{2}{T}$ 中；忽略自旋（适用于特殊的“单态”）。(a) 画出分裂后的能级草图。(b) 利用选择定则 $\Delta m = 0, \pm1$，证明只出现\emph{三条}谱线，位置分别为 $0, \pm\mu_{\text{B}}B/h$。(c) 以 GHz 和皮米（波长）为单位计算分裂量。(d) 多数实际谱线分裂为多于三条的分量（“反常”塞曼效应）：电子自身携带的、哪一种缺失的成分曾是历史上的证据？
\end{exercise}

\begin{exercise}[$\star\star$]\label{exo:b3:quantum-angular-momentum:8}
离心势垒。对氢原子（$V = -e^2/4\pi\varepsilon_0r$），对 $l = 1$ 以 $E_{\text{I}}$ 和 $a_0$ 为单位写出 $U_{\text{eff}}$。(a) 求其极小值点及极小值。(b) 证明当 $r < \dots$ 时 $U_{\text{eff}} >
0$——求出势垒占主导的半径。(c) 比较 $s$ 态与 $p$ 态在 $r = 0$ 附近的 $|\psi|^2$（$u \sim r^{l+1}$，在本阶段不加证明地承认）：哪些态“触及”原子核？(d) 电子俘获——原子核吞并其原子中的一个电子——几乎完全从 $s$ 壳层发生：用一句话解释。
\end{exercise}
